  function bankArtikel() {
    return Core.shuffle(ARTIKEL_WORDS).map(([word, correct]) => {
      const opts = ["der", "die", "das"];
      return {
        prompt: `___ ${word}`,
        options: opts,
        correct: [opts.indexOf(correct)],
        explain: `Richtig heißt es „${correct} ${word}“.`,
      };
    });
  }

