  function getCategory(id) {
    return CATEGORIES.find((c) => c.id === id);
  }

  // Rein deutsche Wort-Paare fürs Memory-Spiel (kein Englisch) — mehrere Spielarten
  function getSynonymPairs() {
    return SYNONYME.map(([word, synonym]) => [word, synonym]);
  }
  function getArtikelPairs() {
    return ARTIKEL_WORDS.map(([word, article]) => [word, `${article} ${word}`]);
  }
  function getPluralPairs() {
    return PLURAL_WORDS.map(([singular, plural]) => [singular, plural]);
  }
  function getRedewendungenPairs() {
    return REDEWENDUNGEN.map(([phrase, meaning]) => [phrase, meaning]);
  }

  const MEMORY_GAMES_DE = [
    { id: "synonyme", label: "Synonyme", icon: "🔁", getPairs: getSynonymPairs },
    { id: "artikel", label: "Artikel", icon: "🏷️", getPairs: getArtikelPairs },
    { id: "plural", label: "Plural", icon: "👥", getPairs: getPluralPairs },
    { id: "redewendungen", label: "Redewendungen", icon: "💬", getPairs: getRedewendungenPairs },
  ];
  /* Memory im Italienisch-Raum: dieselbe Spielmechanik, aber italienische Paare aus
     dem italienischen Wortschatz — Wort und Bedeutung, Wort und Artikel, Wort und
     Betonung. Damit ist auch dieses Spiel im anderen Raum wirklich anders. */
  function itWoerterNachNiveau() {
    return IT_WOERTER.filter((w) => w && w.word && w.de);
  }
  function getItBedeutungPairs() {
    return itWoerterNachNiveau().map((w) => [w.word, w.de]);
  }
  function getItArtikelPairs() {
    return itWoerterNachNiveau()
      .filter((w) => /^(il|lo|la|l'|i|gli|le)\s|^l'/.test(w.word))
      .map((w) => {
        const m = w.word.match(/^(l'|il|lo|la|i|gli|le)\s?(.+)$/);
        return m ? [m[2], m[1]] : null;
      })
      .filter(Boolean);
  }
  function getItBetonungPairs() {
    return itWoerterNachNiveau().filter((w) => w.syl && w.syl.includes("-")).map((w) => [w.word, w.syl]);
  }
  const MEMORY_GAMES_IT = [
    { id: "it-bedeutung", label: "Parola e significato", icon: "🔁", getPairs: getItBedeutungPairs },
    { id: "it-artikel", label: "Articoli", icon: "🏷️", getPairs: getItArtikelPairs },
    { id: "it-betonung", label: "Accento", icon: "🎯", getPairs: getItBetonungPairs },
  ];
  // Nach außen bleibt es EIN Name — der Rest der App muss nichts über Räume wissen.
  const MEMORY_GAMES = new Proxy([], {
    get(_t, prop) {
      const liste = lernraum === "it" ? MEMORY_GAMES_IT : MEMORY_GAMES_DE;
      const wert = liste[prop];
      return typeof wert === "function" ? wert.bind(liste) : wert;
    },
  });

